/**
 * توليد ملف تركيب واحد لقاعدة بيانات جديدة.
 *
 * السبب: المخطط موزّع على ترحيلات متعددة، وحالة قاعدة جديدة تحتاج ترتيباً محدداً
 * (الجداول الأساسية ← المختبر ← منح service_role ← تضييق anon). لصق ملف واحد في
 * Supabase SQL Editor أقل عرضة للخطأ من لصق 13 ملفاً يدوياً.
 *
 * الاستخدام:
 *   npm run db:bundle            # يكتب server/migrations/fresh-install.sql
 *   npm run db:bundle -- --stdout
 *
 * الملف الناتج محتوى مشتق لا أسرار: يمكن حفظه في المستودع.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const migrationsDir = path.resolve(here, '..', 'migrations');
const target = path.join(migrationsDir, 'fresh-install.sql');

/**
 * ترتيب مقصود لقاعدة جديدة. المستثنى صريح ومبرَّر:
 *  - 001_init_analyses_schema, 002_coin_shariah, 004_barcode_scans, 005_case_ledger, 006_case_images:
 *    كل جدولها منشأ أصلاً في 000_full_schema.sql بنفس الأعمدة (`create table if not exists`).
 *  - 003_fix_identity_sequences, 003_cleanup_manual_flags: إصلاحات بيانات لقواعد قديمة فيها صفوف
 *    (setval على أقصى id، وتصحيح أعلام قديمة) — لا معنى لها في قاعدة فارغة.
 *  - 014a_rollback_anon_privileges: تراجع يدوي، ليس تركيباً.
 *  - 001_identity_by_default: مُضمَّنة لأنها تغيّر دلالة `id` إلى `generated by default`
 *    (تطابق شكل القاعدة التي عمل عليها النظام سابقاً)، وهي idempotent.
 */
const ORDER = [
  '000_full_schema.sql',
  '001_identity_by_default.sql',
  '002_health_samples.sql',
  '007_liquidity_workbench.sql',
  '008_liquidity_workbench_points.sql',
  '009_liquidity_workbench_point_time_nullable.sql',
  '010_liquidity_workbench_anon_write.sql',
  '011_liquidity_workbench_grants.sql',
  '012_liquidity_workbench_point_links_service_write.sql',
  '013_liquidity_workbench_anon_write_convention.sql',
  '013b_grant_service_role.sql',
  '014_restrict_anon_privileges.sql',
  '015_manual_liquidity_drawings.sql'
];

const missing = ORDER.filter((f) => !fs.existsSync(path.join(migrationsDir, f)));
if (missing.length) {
  console.error('ترحيلات مفقودة:', missing.join(', '));
  process.exit(1);
}

const parts = [
  '-- =============================================================================',
  '-- ملف تركيب لقاعدة بيانات جديدة — مُولَّد آلياً، لا تُحرّره يدوياً.',
  '-- أعِد توليده بـ: npm run db:bundle',
  `-- الترتيب: ${ORDER.join(' → ')}`,
  '--',
  '-- التنفيذ: Supabase Dashboard ← SQL Editor ← الصق الملف كاملاً ← Run',
  '-- التحقق بعده: السطور المعلَّقة في نهاية القسم الأخير (015).',
  '-- =============================================================================',
  ''
];

for (const file of ORDER) {
  const sql = fs.readFileSync(path.join(migrationsDir, file), 'utf8');
  parts.push(
    '',
    '-- -----------------------------------------------------------------------------',
    `-- ${file}`,
    '-- -----------------------------------------------------------------------------',
    sql.trimEnd(),
    ''
  );
}

const out = `${parts.join('\n')}\n`;
if (process.argv.includes('--stdout')) process.stdout.write(out);
else {
  fs.writeFileSync(target, out, 'utf8');
  const lines = out.split('\n').length;
  console.log(`wrote ${path.relative(process.cwd(), target)} (${lines} lines, ${out.length} bytes)`);
}